/**
 * Motor de Cálculo de Nómina Colombia 2026
 * Valores y normas actualizados para vigencia 2026
 * 
 * SMMLV 2026: $1,750,905 COP
 * Auxilio Transporte 2026: $249,095 COP
 * Jornada Ordinaria: 42 hrs/semana = 210 horas/mes (Ley 2101)
 */

export interface ColombiaPayrollInput {
  employeeId: string;
  firstName: string;
  lastName: string;
  taxId: string;
  baseSalaryMonthly: number;
  daysWorked: number; // 1-30
  extraDiurna: number; // Horas
  extraNocturna: number; // Horas
  recargoNocturno: number; // Horas
  isExempt114_1?: boolean; // Exento de IUE (Art. 114.1)
}

export interface ColombiaPayrollResult {
  employeeId: string;
  employeeName: string;
  taxId: string;
  periodDate: string;
  daysWorked: number;
  
  // DEVENGADO
  baseSalaryEarned: number;
  earnedAuxTransporte: number;
  extraDiurnaValue: number;
  extraNocturnaValue: number;
  recargoNocturnoValue: number;
  overtimeTotal: number;
  grossEarnings: number;
  
  // BASE PARA APORTES
  ibcSecuritySocial: number; // IBC = Salario + Auxilio (si aplica)
  
  // DEDUCCIONES TRABAJADOR
  employeeDeductions: {
    health4pct: number; // Salud 4%
    pension4pct: number; // Pensión 4%
    totalDeductions: number;
  };
  
  netPay: number;
  
  // APORTES EMPLEADOR
  employerContributions: {
    health8_5pct: number; // Salud 8.5%
    pension12pct: number; // Pensión 12%
    sena2pct: number; // SENA 2%
    icbf3pct: number; // ICBF 3%
    totalContributions: number;
  };
  
  hourlyRate: number;
}

const CONSTANTS_2026 = {
  SMMLV: 1750905,
  AUXILIO_TRANSPORTE: 249095,
  SMMLV_LIMIT_AUX: 2 * 1750905, // $3,501,810
  MONTHLY_ORDINARY_HOURS: 210, // 42 hrs/semana × 4.33 semanas
  EXTRA_DIURNA_MULTIPLIER: 1.25, // +25%
  EXTRA_NOCTURNA_MULTIPLIER: 1.75, // +75%
  RECARGO_NOCTURNO_MULTIPLIER: 1.35, // +35%
};

export class ColombiaPayrollEngine {
  static calculate(input: ColombiaPayrollInput): ColombiaPayrollResult {
    // ============================================
    // 1. CÁLCULO DE SALARIO DEVENGADO
    // ============================================
    
    // Salario proporcional por días trabajados
    const baseSalaryEarned = (input.baseSalaryMonthly / 30) * input.daysWorked;
    
    // Auxilio de Transporte (aplica si salario ≤ 2 SMMLV)
    let earnedAuxTransporte = 0;
    if (input.baseSalaryMonthly <= CONSTANTS_2026.SMMLV_LIMIT_AUX) {
      earnedAuxTransporte = (CONSTANTS_2026.AUXILIO_TRANSPORTE / 30) * input.daysWorked;
    }
    
    // TASA HORARIA para cálculo de extras
    const hourlyRate = input.baseSalaryMonthly / CONSTANTS_2026.MONTHLY_ORDINARY_HOURS;
    
    // ============================================
    // 2. CÁLCULO DE HORAS EXTRAS (CORRECCIÓN)
    // ============================================
    
    const extraDiurnaValue = input.extraDiurna * hourlyRate * CONSTANTS_2026.EXTRA_DIURNA_MULTIPLIER;
    const extraNocturnaValue = input.extraNocturna * hourlyRate * CONSTANTS_2026.EXTRA_NOCTURNA_MULTIPLIER;
    const recargoNocturnoValue = input.recargoNocturno * hourlyRate * CONSTANTS_2026.RECARGO_NOCTURNO_MULTIPLIER;
    const overtimeTotal = extraDiurnaValue + extraNocturnaValue + recargoNocturnoValue;
    
    // ============================================
    // 3. TOTAL DEVENGADO
    // ============================================
    
    const grossEarnings = baseSalaryEarned + earnedAuxTransporte + overtimeTotal;
    
    // ============================================
    // 4. CÁLCULO DE IBC (Base para Aportes Seguridad Social)
    // ============================================
    // IBC = Salario base + Auxilio de Transporte (si aplica)
    // Nota: Las horas extras NO se incluyen en IBC
    
    const ibcSecuritySocial = baseSalaryEarned + earnedAuxTransporte;
    
    // ============================================
    // 5. DEDUCCIONES DEL TRABAJADOR (sobre IBC)
    // ============================================
    
    const health4pct = ibcSecuritySocial * 0.04;
    const pension4pct = ibcSecuritySocial * 0.04;
    const totalDeductions = health4pct + pension4pct;
    
    // ============================================
    // 6. NETO A PAGAR
    // ============================================
    
    const netPay = grossEarnings - totalDeductions;
    
    // ============================================
    // 7. APORTES EMPLEADOR (CORRECCIÓN)
    // ============================================
    // Los aportes del empleador se calculan sobre IBC
    
    const health8_5pct = ibcSecuritySocial * 0.085; // Salud 8.5%
    const pension12pct = ibcSecuritySocial * 0.12; // Pensión 12%
    const sena2pct = ibcSecuritySocial * 0.02; // SENA 2%
    const icbf3pct = ibcSecuritySocial * 0.03; // ICBF 3%
    
    const totalContributions = health8_5pct + pension12pct + sena2pct + icbf3pct;
    
    // ============================================
    // 8. RESULTADO FINAL
    // ============================================
    
    return {
      employeeId: input.employeeId,
      employeeName: `${input.firstName} ${input.lastName}`,
      taxId: input.taxId,
      periodDate: new Date().toISOString().split('T')[0],
      daysWorked: input.daysWorked,
      
      baseSalaryEarned,
      earnedAuxTransporte,
      extraDiurnaValue,
      extraNocturnaValue,
      recargoNocturnoValue,
      overtimeTotal,
      grossEarnings,
      
      ibcSecuritySocial,
      
      employeeDeductions: {
        health4pct,
        pension4pct,
        totalDeductions,
      },
      
      netPay,
      
      employerContributions: {
        health8_5pct,
        pension12pct,
        sena2pct,
        icbf3pct,
        totalContributions,
      },
      
      hourlyRate,
    };
  }
}

export default ColombiaPayrollEngine;